/** A small installable app on its own subdomain: its page, install files and icons. */
function smallApp(url, page, files, images, home) {
  const p = url.pathname;
  if (p === "/robots.txt") return new Response("User-agent: *\nAllow: /\nSitemap: " + home + "sitemap.xml\n",{headers:{"content-type":"text/plain"}});
  if (p === "/sitemap.xml") return new Response('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>' + home + '</loc><changefreq>weekly</changefreq></url></urlset>',{headers:{"content-type":"application/xml; charset=utf-8"}});
  if (files[p]) { const [type, body] = files[p]; return new Response(body,{headers:{"content-type":type,"cache-control":p==="/sw.js"?"no-cache":"public, max-age=3600","x-content-type-options":"nosniff"}}); }
  if (images[p]) return new Response(Uint8Array.from(atob(images[p]),c=>c.charCodeAt(0)),{headers:{"content-type":"image/png","cache-control":"public, max-age=86400"}});
  if (p === "/" || p === "/index.html") return new Response(page,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-cache","x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin"}});
  return Response.redirect(home, 302);
}

/** HaniaPlate's fallback when a phone cannot reach data.gov.il itself: only the Ministry of Transport
 *  vehicle tables, only a plate or model filter, cached for six hours. */
const PLATE_RES = new Set(["053cea08-09bc-40ec-8f7a-156f0677aff3","56063a99-8a3e-4ff4-912e-5966c0279bad","bb2355dc-9ec7-4f06-9c3f-3344672171da","36bf1404-0be4-49d2-82dc-2f1ead4a8b93","c8b9f9c8-4612-4068-934f-d4acd2e3c06e","bf9df4e2-d90d-4c0a-a400-19e15af8e95f","cd3acc5c-03c3-4c89-9c54-d40f93c0d790","03adc637-b6fe-402b-9937-7c3d3afc9140","f6efe89a-fb3d-43a4-bb61-9bf12a9b9099","851ecab1-0622-4dbe-a6c7-f950cf82abf9","142afde2-6228-49f9-8a29-9b6c3a0cbe40"]);
const PLATE_KEYS = new Set(["mispar_rechev","MISPAR_RECHEV","MISPAR RECHEV","tozeret_cd","degem_cd","shnat_yitzur"]);
async function plateProxy(url, ctx) {
  const bad = (m) => new Response(JSON.stringify({ success: false, error: m }), { status: 400, headers: { "content-type": "application/json" } });
  const rid = url.searchParams.get("resource_id"); if (!PLATE_RES.has(rid)) return bad("resource");
  let f; try { f = JSON.parse(url.searchParams.get("filters") || ""); } catch { return bad("filters"); }
  if (!f || typeof f !== "object" || !Object.keys(f).length || Object.entries(f).some(([k, v]) => !PLATE_KEYS.has(k) || !/^\d{1,9}$/.test(String(v)))) return bad("filters");
  const q = new URLSearchParams({ resource_id: rid, filters: JSON.stringify(f), limit: String(Math.min(50, +url.searchParams.get("limit") || 50)) });
  const sort = url.searchParams.get("sort"); if (sort === "baalut_dt desc") q.set("sort", sort);
  const target = "https://data.gov.il/api/3/action/datastore_search?" + q, key = new Request(target), cache = caches.default;
  const hit = await cache.match(key); if (hit) return hit;
  const r = await fetch(target, { headers: { accept: "application/json", "user-agent": "HaniaCheck/1 (+https://check.hania360.com)" } }).catch(() => ({ ok: false, status: 0 }));
  if (!r.ok) return new Response(JSON.stringify({ success: false, error: "upstream " + r.status }), { status: 502, headers: { "content-type": "application/json" } });
  const res = new Response(await r.text(), { headers: { "content-type": "application/json", "cache-control": "public, max-age=21600" } });
  ctx && ctx.waitUntil && ctx.waitUntil(cache.put(key, res.clone()));
  return res;
}

/** HaniaCheck's other registers, when a phone cannot reach data.gov.il itself: only these packages and
 *  their own tables, read-only searches, cached for six hours. */
const CHECK_PKGS = new Set(["ica_companies","ica-deletion","membership-in-liquidation","pinkashakablanim","metavhim","moj-amutot","musachim","pensia-net","gemelnet","kosherbusiness","agg_charge_stations"]);
const jsonRes = (o, status = 200, extra = {}) => new Response(JSON.stringify(o), { status, headers: Object.assign({ "content-type": "application/json; charset=utf-8" }, extra) });
async function cachedGet(target, ctx, ttl, headers) {
  const key = new Request(target), cache = caches.default;
  const hit = await cache.match(key); if (hit) return hit;
  const r = await fetch(target, { headers: Object.assign({ accept: "application/json", "user-agent": "HaniaCheck/1 (+https://check.hania360.com)" }, headers || {}) }).catch(() => ({ ok: false, status: 0 }));
  if (!r.ok) return jsonRes({ success: false, error: "upstream " + r.status }, 502);
  const res = new Response(await r.text(), { headers: { "content-type": "application/json; charset=utf-8", "cache-control": "public, max-age=" + ttl } });
  ctx && ctx.waitUntil && ctx.waitUntil(cache.put(key, res.clone()));
  return res;
}
async function allowedTables(ctx) {
  const ids = new Set();
  for (const pkg of CHECK_PKGS) {
    const r = await cachedGet("https://data.gov.il/api/3/action/package_show?id=" + encodeURIComponent(pkg), ctx, 86400);
    if (!r.ok) continue;
    const j = await r.json().catch(() => null);
    for (const t of (j && j.result && j.result.resources) || []) ids.add(t.id);
  }
  return ids;
}
async function dsProxy(url, ctx) {
  const sp = url.searchParams, action = sp.get("action");
  if (action === "package_show") {
    const id = sp.get("id"); if (!CHECK_PKGS.has(id)) return jsonRes({ success: false, error: "package" }, 400);
    return cachedGet("https://data.gov.il/api/3/action/package_show?id=" + encodeURIComponent(id), ctx, 86400);
  }
  if (action !== "datastore_search") return jsonRes({ success: false, error: "action" }, 400);
  const rid = sp.get("resource_id") || "";
  if (!/^[0-9a-f-]{36}$/.test(rid) || !(await allowedTables(ctx)).has(rid)) return jsonRes({ success: false, error: "resource" }, 400);
  const q = new URLSearchParams({ resource_id: rid, limit: String(Math.max(1, Math.min(2000, +sp.get("limit") || 15))) });
  const text = sp.get("q"); if (text) { if (text.length > 80) return jsonRes({ success: false, error: "q" }, 400); q.set("q", text); }
  const f = sp.get("filters");
  if (f) { let o; try { o = JSON.parse(f); } catch { return jsonRes({ success: false, error: "filters" }, 400); }
    if (!o || typeof o !== "object" || Object.entries(o).some(([k, v]) => k.length > 40 || (typeof v !== "string" && typeof v !== "number") || String(v).length > 40)) return jsonRes({ success: false, error: "filters" }, 400);
    q.set("filters", JSON.stringify(o)); }
  const sort = sp.get("sort"); if (sort) { if (!/^[\w ]{1,40} (asc|desc)$/.test(sort)) return jsonRes({ success: false, error: "sort" }, 400); q.set("sort", sort); }
  return cachedGet("https://data.gov.il/api/3/action/datastore_search?" + q, ctx, 21600);
}

/** HaniaCheck apartments: deals reported to the Tax Authority around an address, through GovMap. */
async function nadlanApi(url, ctx) {
  const q = (url.searchParams.get("q") || "").trim().slice(0, 80);
  if (q.length < 4) return jsonRes({ ok: false, error: "address" }, 400);
  const cache = caches.default, key = new Request("https://check.hania360.com/api/nadlan?q=" + encodeURIComponent(q));
  const hit = await cache.match(key); if (hit) return hit;
  const G = "https://www.govmap.gov.il/api/", H = { accept: "application/json", "content-type": "application/json", "user-agent": "Mozilla/5.0 (HaniaCheck; +https://check.hania360.com)", origin: "https://www.govmap.gov.il", referer: "https://www.govmap.gov.il/" };
  const get = async (u) => { const r = await fetch(u, { headers: H }).catch(() => null); return r && r.ok ? r.json().catch(() => null) : null; };
  try {
    const ac = await fetch(G + "search-service/autocomplete", { method: "POST", headers: H, body: JSON.stringify({ searchText: q, language: "he", isAccurate: false, maxResults: 10 }) }).then((r) => (r.ok ? r.json() : null)).catch(() => null);
    if (!ac) return jsonRes({ ok: false, error: "upstream" }, 502);
    const pts = (ac.results || []).map((r) => { const m = /^POINT\(([-\d.]+) ([-\d.]+)\)/.exec(r.shape || ""); return m ? { text: r.text, x: m[1], y: m[2] } : null; }).filter(Boolean);
    if (!pts.length) return jsonRes({ ok: false, error: "address" });
    let place = pts[0], polys = [];
    for (const p of pts.slice(0, 3)) {
      for (const rad of [80, 250]) { const d = await get(G + "real-estate/deals/" + p.x + "," + p.y + "/" + rad); if (Array.isArray(d) && d.length) { polys = d; place = p; break; } }
      if (polys.length) break;
    }
    const ids = [...new Set(polys.map((p) => p.polygon_id).filter(Boolean))].slice(0, 4), seen = new Set(), deals = [];
    const add = (rows, type) => { for (const d of rows || []) { const id = d.objectid || [d.dealDate, d.dealAmount, d.streetName, d.houseNumber, d.floor].join("|"); if (seen.has(id) || !(+d.dealAmount > 0)) continue; seen.add(id);
      deals.push({ date: String(d.dealDate || "").slice(0, 10), price: +d.dealAmount, area: +d.assetArea || 0, rooms: +d.assetRoomNum || 0, floor: d.floor || "", street: d.streetName || "", house: d.houseNumber || "", city: d.settlementNameHeb || "", type: type || d.propertyTypeDescription || "" }); } };
    const since = (new Date().getFullYear() - 6) + "-01";
    for (const id of ids) { for (const t of [2, 1]) { const d = await get(G + "real-estate/street-deals/" + encodeURIComponent(id) + "?limit=60&dealType=" + t + "&startDate=" + since); add(d && d.data, t === 1 ? "יד ראשונה" : ""); } }
    if (deals.length < 12 && ids[0]) { const d = await get(G + "real-estate/neighborhood-deals/" + encodeURIComponent(ids[0]) + "?limit=60&dealType=2&startDate=" + since); add(d && d.data, ""); }
    deals.sort((a, b) => (a.date < b.date ? 1 : -1));
    const res = jsonRes({ ok: true, address: place.text, deals: deals.slice(0, 120) }, 200, { "cache-control": "public, max-age=86400" });
    ctx && ctx.waitUntil && ctx.waitUntil(cache.put(key, res.clone()));
    return res;
  } catch { return jsonRes({ ok: false, error: "upstream" }, 502); }
}

/** A guest's invitation link: the same page, with a WhatsApp preview of this event (title, date, photo). */
async function invitationPage(env, url, id) {
  let ev = null;
  try { if (env.HAZMANA) ev = (await env.HAZMANA.get(env.HAZMANA.idFromName("e:" + id)).fetch("https://e/open?e=" + id).then((r) => r.json())).event; } catch {}
  const esc = (x) => String(x || "").replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
  let html = HZAPP;
  if (ev) {
    const d = ev.date ? new Date(ev.date + "T12:00:00") : null, when = d ? ["ראשון", "שני", "שלישי", "רביעי", "חמישי", "שישי", "שבת"][d.getDay()] + ", " + d.getDate() + "." + (d.getMonth() + 1) + "." + d.getFullYear() : "";
    const desc = [when && "יום " + when, ev.time, ev.venue].filter(Boolean).join(" · ") + " · לחצו לפרטים ולאישור הגעה";
    const img = ev.photo ? "https://hazmana.hania360.com/api/hz/photo?e=" + id : "https://hania360.com/og/hazmana.jpg";
    const tags = '<meta property="og:type" content="website"><meta property="og:site_name" content="HaniaHazmana"><meta property="og:title" content="' + esc("💌 " + (ev.title || "הזמנה")) + '"><meta property="og:description" content="' + esc(desc) + '"><meta property="og:image" content="' + img + '"><meta property="og:url" content="' + esc(url.origin + url.pathname) + '"><meta property="og:locale" content="he_IL"><meta name="twitter:card" content="summary_large_image"><meta name="robots" content="noindex">';
    html = html.replace("</head>", tags + "</head>").replace(/<title>[^<]*<\/title>/, "<title>" + esc((ev.title || "הזמנה") + " · הזמנה") + "</title>");
  }
  return new Response(html, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache", "x-og": ev ? "1" : "0", "x-robots-tag": "noindex", "referrer-policy": "strict-origin-when-cross-origin" } });
}

