export default {
  async fetch(request, env, ctx) {
    let response = await this.route(request, env, ctx);
    if (response.status === 101 || response.webSocket) return response;
    try { response = decorate(response, new URL(request.url)); } catch {}
    if (env && env.ENVIRONMENT === "staging") { const r = new Response(response.body, response); r.headers.set("x-robots-tag", "noindex"); return r; }
    return response;
  },
  async route(request, env, ctx) {
    const url = new URL(request.url);
    // Usage counts from every site, and the link-preview images and the owner's dashboard on hania360.com.
    if (url.pathname === "/api/stat") return statApi(request, env || {}, url, ctx);
    if (url.hostname === "hania360.com" && url.pathname.startsWith("/og/")) { const r = ogImage(url); if (r) return r; }
    if (url.hostname === "hania360.com" && url.pathname === "/stats") return statsPage(request, env || {}, url);
    // One address for search engines: www.hania360.com moves to hania360.com.
    if (url.hostname === "home.hania360.com" || url.searchParams.get("app") === "home" && /workers\.dev$/.test(url.hostname)) return homeApp(url);
    if (url.hostname === "caption.hania360.com" || url.searchParams.get("app") === "caption" && /workers\.dev$/.test(url.hostname)) return smallApp(url, CAPTIONAPP, CAPTION_FILES, CAPTION_IMAGES, "https://caption.hania360.com/");
    if (url.hostname === "ezra.hania360.com" || url.searchParams.get("app") === "ezra" && /workers\.dev$/.test(url.hostname)) return smallApp(url, EZRAAPP, EZRA_FILES, EZRA_IMAGES, "https://ezra.hania360.com/");
    if ((url.hostname === "hania360.com" || url.hostname === "www.hania360.com" || /workers\.dev$/.test(url.hostname)) && url.pathname === "/api/ai-usage") {
      // How many Workers AI jobs each app ran per day (no personal data), for the daily cost check.
      if (!env || !env.SIPUR) return Response.json({ error: "unavailable" }, { status: 503 });
      const r = await env.SIPUR.get(env.SIPUR.idFromName("limits")).fetch("https://l/usage");
      return new Response(r.body, { headers: { "content-type": "application/json", "cache-control": "public, max-age=300", "access-control-allow-origin": "*" } });
    }
    if (url.hostname === "sefer.hania360.com" || url.searchParams.get("app") === "sefer" && /workers\.dev$/.test(url.hostname)) return url.pathname === "/api/sefer/book" ? seferApi(request, env || {}) : url.pathname === "/api/sefer/hear" ? hearApi(request, env || {}) : smallApp(url, SEFERAPP, SEFER_FILES, SEFER_IMAGES, "https://sefer.hania360.com/");
    if (url.hostname === "play.hania360.com" || url.searchParams.get("app") === "play" && /workers\.dev$/.test(url.hostname)) return playApp(request, env || {});
    if (url.hostname === "kibud.hania360.com" || url.searchParams.get("app") === "kibud" && /workers\.dev$/.test(url.hostname)) return url.pathname.startsWith("/api/kibud/") ? kibudApi(request, env || {}, url) : smallApp(url, KIBUDAPP, KIBUD_FILES, KIBUD_IMAGES, "https://kibud.hania360.com/");
    if (url.hostname === "kita.hania360.com" || url.searchParams.get("app") === "kita" && /workers\.dev$/.test(url.hostname)) return url.pathname === "/api/kita/sheet" ? sheetApi(request, env || {}) : smallApp(url, KITAAPP, KITA_FILES, KITA_IMAGES, "https://kita.hania360.com/");
    if (url.hostname === "sipur.hania360.com" || url.searchParams.get("app") === "sipur" && /workers\.dev$/.test(url.hostname)) return url.pathname === "/api/sipur/story" ? storyApi(request, env || {}) : smallApp(url, SIPURAPP, SIPUR_FILES, SIPUR_IMAGES, "https://sipur.hania360.com/");
    if (url.hostname === "hazmana.hania360.com" || url.searchParams.get("app") === "hazmana" && /workers\.dev$/.test(url.hostname)) {
      if (url.pathname.startsWith("/api/hz/")) return hazmanaApi(request, env || {}, url);
      const inv = url.pathname.match(/^\/i\/([A-Za-z0-9]{6,24})(?:\/[A-Za-z0-9]{6,20})?\/?$/);
      if (inv) return invitationPage(env || {}, url, inv[1]);
      return smallApp(url, HZAPP, HZ_FILES, HZ_IMAGES, "https://hazmana.hania360.com/");
    }
    if (url.hostname === "tisa.hania360.com" || url.searchParams.get("app") === "tisa" && /workers\.dev$/.test(url.hostname)) {
      if (url.pathname === "/api/me" || url.pathname.startsWith("/api/me/")) return meApi(request, env, ctx);
      if (url.pathname.startsWith("/api/tisa/")) return tisaApi(request, env, url);
      return smallApp(url, TISAAPP, TISA_FILES, TISA_IMAGES, "https://tisa.hania360.com/");
    }
    if (url.hostname === "years.hania360.com" || url.searchParams.get("app") === "years" && /workers\.dev$/.test(url.hostname)) return smallApp(url, YEARSAPP, YEARS_FILES, YEARS_IMAGES, "https://years.hania360.com/");
    // HaniaPlate grew into HaniaCheck; old links keep working (the #plate stays on the address).
    if (url.hostname === "plate.hania360.com") return url.pathname === "/api/plate" ? plateProxy(url, ctx) : Response.redirect("https://check.hania360.com/", 301);
    if (url.hostname === "check.hania360.com" || url.searchParams.get("app") === "check" && /workers\.dev$/.test(url.hostname)) {
      if (url.pathname === "/api/me" || url.pathname.startsWith("/api/me/")) return meApi(request, env, ctx);
      if (url.pathname === "/api/plate") return plateProxy(url, ctx);
      if (url.pathname === "/api/ds") return dsProxy(url, ctx);
      if (url.pathname === "/api/nadlan") return nadlanApi(url, ctx);
      return smallApp(url, CHECKAPP, CHECK_FILES, CHECK_IMAGES, "https://check.hania360.com/");
    }
    if (url.hostname === "ride.hania360.com" || url.searchParams.get("app") === "ride" && /workers\.dev$/.test(url.hostname)) return url.pathname.startsWith("/api/ride/") ? rideApi(request, env || {}, url) : smallApp(url, RIDEAPP, RIDE_FILES, RIDE_IMAGES, "https://ride.hania360.com/");
    if (url.hostname === "gamad.hania360.com" || url.searchParams.get("app") === "gamad" && /workers\.dev$/.test(url.hostname)) return url.pathname.startsWith("/api/gamad/") ? gamadApi(request, env || {}, url) : smallApp(url, GAMADAPP, GAMAD_FILES, GAMAD_IMAGES, "https://gamad.hania360.com/");
    // HaniaDat (was HaniaShabbat): the same app at both addresses, so phones that installed it or turned on reminders keep working.
    if (url.hostname === "dat.hania360.com" || url.hostname === "shabbat.hania360.com" || /^(shabbat|dat)$/.test(url.searchParams.get("app") || "") && /workers\.dev$/.test(url.hostname)) return url.pathname.startsWith("/api/shabbat/") ? shabbatApi(request, env || {}) : smallApp(url, SHABBATAPP, SHABBAT_FILES, SHABBAT_IMAGES, "https://dat.hania360.com/");
    if (url.hostname === "quiz.hania360.com" || url.searchParams.get("app") === "quiz" && /workers\.dev$/.test(url.hostname)) return url.pathname.startsWith("/api/") ? quizApi(request, env || {}, url) : smallApp(url, QUIZAPP, QUIZ_FILES, QUIZ_IMAGES, "https://quiz.hania360.com/");
    if (url.hostname === "park.hania360.com" || url.searchParams.get("app") === "park" && /workers\.dev$/.test(url.hostname)) return url.pathname.startsWith("/api/park/") ? parkApi(request, env || {}) : smallApp(url, PARKAPP, PARK_FILES, PARK_IMAGES, "https://park.hania360.com/");
    if (url.hostname === "pick.hania360.com" || url.searchParams.get("app") === "pick" && /workers\.dev$/.test(url.hostname)) return pickApp(url);
    if (url.hostname === "bills.hania360.com" || url.searchParams.get("app") === "bills" && /workers\.dev$/.test(url.hostname)) return bill(url);
    if (url.hostname === "www.hania360.com") return Response.redirect("https://hania360.com" + url.pathname + url.search, 301);
    const GUIDES=guidesPage();
    const pages = {"/":HOME,"/index.html":HOME,"/guides":GUIDES,"/guides/":GUIDES,...ARTICLE_PAGES,"/about":ABOUT,"/privacy":PRIVACY,"/terms":TERMS,"/contact":CONTACT};
    // ads.txt for Google AdSense. The Worker owns all apex-domain paths.
    if (url.pathname === "/ads.txt") return new Response("google.com, pub-5716914780099032, DIRECT, f08c47fec0942fa0\n",{headers:{"content-type":"text/plain; charset=utf-8","cache-control":"public, max-age=3600"}});
    // Canonicalize known routes with a trailing slash.
    if (url.pathname.length > 1 && url.pathname.endsWith("/") && pages[url.pathname.slice(0,-1)]) return Response.redirect(url.origin + url.pathname.slice(0,-1) + url.search, 301);
    if (url.pathname === "/robots.txt") return new Response("User-agent: *\nAllow: /\nSitemap: https://hania360.com/sitemap.xml\n",{headers:{"content-type":"text/plain; charset=utf-8"}});
    if (url.pathname === "/sitemap.xml") {
      const paths=["","guides",...ARTICLES.filter(onTopic).map(a=>"guides/"+a.slug),"about","privacy","terms","contact"];
      const xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+paths.map(p=>'<url><loc>https://hania360.com/'+p+'</loc><lastmod>2026-10-22</lastmod></url>').join("")+'</urlset>';
      return new Response(xml,{headers:{"content-type":"application/xml; charset=utf-8"}});
    }
    // The old address of HaniaBills: the page takes the list saved in this browser along to bills.hania360.com.
    if (url.pathname === "/bills" || url.pathname === "/bills/") return new Response(BILLS_MOVE,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-cache","x-robots-tag":"noindex"}});
    if (url.pathname === "/bills-sw.js") return new Response("self.addEventListener('install',()=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.registration.unregister()));",{headers:{"content-type":"text/javascript; charset=utf-8","cache-control":"no-cache"}});
    if (url.pathname.startsWith("/bills/")) return Response.redirect("https://bills.hania360.com" + url.pathname.slice(6) + url.search, 301);
    const page=pages[url.pathname];
    if (!page) return new Response(layout("העמוד לא נמצא | Hania360","העמוד המבוקש לא נמצא.",`<article class="legal"><h1>העמוד לא נמצא</h1><p>ייתכן שהקישור שגוי או שהעמוד הועבר.</p><p><a href="/">לדף הבית</a> · <a href="/guides">לכל המדריכים</a></p></article>`,url.pathname),{status:404,headers:{"content-type":"text/html; charset=utf-8"}});
    return new Response(page,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin"}});
  }
};
